import json,pathlib
rows=[
(1950,1958,'Canary Islands → Venezuela','ESP','VEN','An Atlantic chapter','Postwar hardship and established family networks encouraged emigration from the Canary Islands to Venezuela. This regional story belongs within Spain; national migration estimates cannot isolate island departures.','https://www.gobiernodecanarias.org/educacion/web/dts/educacion/publicaciones/pdf/canarias-en-la-historia_recursos-aula.pdf'),
(1955,1955,'Italy → Germany','ITA','DEU','Recruiting for reconstruction','The December 1955 recruitment agreement opened a formal route for Italian workers to West Germany. Postwar demand for labor shaped new migration networks.','https://www.bundesregierung.de/breg-en/service/archive/merkel-festive-event-integration-1956100'),
(1956,1956,'Hungary → Austria','HUN','AUT','Flight after the uprising','The Hungarian uprising and Soviet repression in October and November 1956 forced people to seek safety across the Austrian border.','https://www.unhcr.org/news/stories/fiftieth-anniversary-hungarian-uprising-and-refugee-crisis'),
(1961,1961,'Türkiye → Germany','TUR','DEU','A new labor corridor','The recruitment agreement of 30 October 1961 connected Turkish workers with West German employers. Family and community networks would give this migration a lasting significance.','https://www.bundesregierung.de/breg-en/service/archive/merkel-festive-event-integration-1956100'),
(1962,1962,'Algeria → France','DZA','FRA','Independence and departure','Algerian independence was accompanied by departures to France. European settlers and threatened Algerians, including harkis and their families, faced different circumstances and risks.','https://www.histoire-immigration.fr/exposition-permanente/1962'),
(1972,1972,'Uganda → United Kingdom','UGA','GBR','Expelled from home','The August 1972 expulsion of Ugandan Asians forced families to leave. Many found refuge in the United Kingdom.','https://www.nationalarchives.gov.uk/education/resources/ugandan-asians/'),
(1975,1975,'Angola → Portugal','AGO','PRT','Decolonization and evacuation','Angolan independence and escalating conflict prompted departures and an evacuation airlift to Portugal. Colonial ties shaped the route.','https://www.arquivo.presidencia.pt/details?id=26990'),
(1981,1981,'Poland → Germany','POL','DEU','Life under martial law','Martial law imposed on 13 December 1981 and political repression accompanied emigration from Poland, including to West Germany.','https://www.bpb.de/themen/migration-integration/dossier-migration/252241/geschichte-der-migration-in-deutschland/'),
(1989,1995,'Romania → Germany','ROU','DEU','Borders and possibilities','The Romanian revolution and the end of restrictions on mobility changed opportunities to move. Germany became a significant destination during the following years.','https://www.bpb.de/themen/migration-integration/regionalprofile/english-version-country-profiles/58541/immigration-and-emigration-since-1990/'),
(1992,1995,'Bosnia and Herzegovina → Germany','BIH','DEU','Displaced by war','War in Bosnia and Herzegovina forced people to seek safety across Europe, including in Germany. Displacement, temporary protection and later returns shaped these journeys.','https://www.unhcr.org/sites/default/files/legacy-pdf/3ebf9bb50.pdf'),
(1998,1999,'Colombia → Spain','COL','ESP','Across a shared language','Colombia’s 1998–1999 economic crisis, Spanish employment opportunities and a shared language contributed to increased emigration to Spain. This was a combination of pressures and opportunities, rather than a single starting point.','https://www.cancilleria.gov.co/en/node/142'),
(2004,2004,'Poland → United Kingdom','POL','GBR','An enlarged Europe','EU enlargement on 1 May 2004 and access to the UK labor market created new opportunities for Polish workers and families.','https://www.ons.gov.uk/peoplepopulationandcommunity/populationandmigration/populationestimates/articles/detailedcountryofbirthandnationalityanalysis/2013-05-16'),
(2008,2013,'Spain → Germany','ESP','DEU','Looking for opportunity','The financial and employment crisis accompanied renewed migration from Spain to Germany. Work, family ties and individual circumstances influenced decisions.','https://www.bundestag.de/webarchiv/presse/hib/2014_01/01-260896'),
(2011,2015,'Syria → Germany','SYR','DEU','Seeking safety','Civil war in Syria forced millions from their homes. Germany became an important European destination, with substantial arrivals later in this period.','https://www.bpb.de/themen/migration-integration/regionalprofile/english-version-country-profiles/262813/refuge-and-asylum-in-germany/'),
(2014,2024,'Ukraine → Poland','UKR','POL','A changing eastern border','Russian aggression beginning in 2014 and associated economic deterioration intensified migration from Ukraine to Poland. Work and existing networks also shaped the corridor.','https://www.gov.pl/web/denmark/facts-about-the-russias-war-and-the-situation-at-the-polish-ukrainian-border'),
(2015,2019,'Venezuela → Spain','VEN','ESP','A deepening crisis','Political, economic and humanitarian crisis contributed to an escalating Venezuelan migration wave. Spain was one destination; migration on this route predates the crisis.','https://www.acnur.org/es-es/noticias/historias/informacion-sobre-proteccion-internacional-para-nacionales-venezolanos-en-espana'),
(2020,2024,'Belarus → Poland','BLR','POL','Beyond the border','Following the August 2020 election and repression in Belarus, migration to Poland intensified. The Polish Office for Foreigners identifies increased residence applications after the election and again after the February 2022 invasion of Ukraine. Its permit and protection figures describe administrative measures, not direct migration counts.','https://www.gov.pl/web/udsc/dane-migracyjne-dotyczace-obywateli-bialorusi'),
(2022,2024,'Ukraine → Poland','UKR','POL','Forced to leave','Russia’s full-scale invasion on 24 February 2022 triggered large-scale displacement. Poland welcomed people fleeing Ukraine. Border crossings and refugee registrations are distinct from the modelled migration estimates on this map.','https://www.unhcr.org/news/press/2022/3/6234811a4.html')]
events=[dict(zip(['start','end','route','origin','destination','title','text','source'],r),id=i) for i,r in enumerate(rows)]
events[15]['additionalSource'] = 'https://www.acnur.org/es-es/noticias/comunicados-de-prensa/las-solicitudes-de-asilo-de-personas-venezolanas-sobrepasan-las-400'
for event in events:
    event['scope'] = 'route'
events.extend([
    dict(id=18, scope='origin-country', country='VEN', start=2014, end=2024,
         title='Political, economic and humanitarian crisis',
         text='The recent Venezuelan exodus intensified from 2014 during a prolonged political, economic and humanitarian crisis. UNHCR documented people leaving amid insecurity and violence, loss of income, and shortages of food, medicines and essential services. These country-wide pressures provide context for emigration to different destinations; individual circumstances and routes vary. This featured period does not mark the beginning of all Venezuelan migration or assign the selected migration total to a single cause.',
         source='https://data.unhcr.org/en/documents/download/63883',
         additionalSource='https://rmrp.r4v.info/eyr2024/'),
    dict(id=19, scope='origin-country', country='VEN', start=2024, end=2024,
         title='Election uncertainty and mobility constraints',
         text='R4V reported renewed uncertainty and heightened tension following the 2024 Venezuelan presidential election. Interruptions affecting diplomatic and consular access and travel created difficulties with documentation, family reunification and protection. This is context for Venezuelan outward movement during 2024, rather than a quantified explanation for a particular destination or for earlier migration.',
         source='https://rmrp.r4v.info/eyr2024/')
])
# Country-wide accounts are dated to their sources and do not attribute a count to a cause.
events.extend([
 dict(id=20,scope='origin-country',country='SDN',start=2023,end=2024,title='War and displacement from Sudan',text='Armed conflict beginning in April 2023 forced people from their homes within Sudan and across borders, including to Chad, Egypt, South Sudan and other neighbouring countries. These movements include refugees and people returning to their own countries; they are not equivalent to a particular bilateral migration total.',source='https://data.unhcr.org/en/situations/sudansituation'),
 dict(id=21,scope='origin-country',country='AFG',start=2021,end=2024,title='Political upheaval and humanitarian crisis',text='Conflict and the August 2021 takeover, economic deterioration and drought contributed to displacement in and from Afghanistan. Experiences and destinations differ; the context does not assign the migration figures to a specific cause.',source='https://crisisresponse.iom.int/response/afghanistan-crisis-response-plan-2020-2021/year/2021',additionalSource='https://crisisresponse.iom.int/response/afghanistan-and-neighbouring-countries-crisis-response-plan-2023'),
 dict(id=22,scope='origin-country',country='SYR',start=2011,end=2016,title='Conflict and displacement from Syria',text='The Syrian conflict forced people to seek safety inside Syria and in neighbouring countries, with some later moving onward. UNHCR documented refugee movements and protection needs in the region. Refugee counts and annual migration flows are different measures.',source='https://www.unhcr.org/uk/news/news-releases/unhcr-total-number-syrian-refugees-exceeds-four-million-first-time'),
 dict(id=23,scope='origin-country',country='UKR',start=2022,end=2024,title='Full-scale invasion and displacement',text='Russia’s full-scale invasion in February 2022 caused large-scale displacement within Ukraine and across borders. Many people fled to neighbouring countries and elsewhere in Europe. Border crossings and refugee registrations do not equal long-term bilateral migration flows.',source='https://www.unhcr.org/uk/news/briefing-notes/unhcr-mobilizing-aid-forcibly-displaced-ukraine-and-neighbouring-countries',additionalSource='https://data.unhcr.org/en/situations/ukraine')
])
# Additional worldwide accounts: narrow date windows, with no causal allocation
# of the map's counts. A source's retrospective publication date is distinct from
# the year of the described event.
events.extend([
 dict(id=24,scope='route',origin='MMR',destination='BGD',route='Myanmar → Bangladesh',start=2017,end=2017,title='Rohingya flight to Bangladesh',text='Violence and persecution in Myanmar’s Rakhine State prompted large-scale Rohingya flight to Bangladesh from August 2017. This refugee movement is documented separately from the annual residence-flow statistics; it does not explain every movement on this corridor.',source='https://bangladesh.un.org/en/277639-seven-years-rohingya-refugee-influx-bangladesh-unhcr-reminds-need-international-solidarity'),
 dict(id=25,scope='route',origin='SSD',destination='UGA',route='South Sudan → Uganda',start=2016,end=2017,title='Renewed conflict and refuge in Uganda',text='Renewed fighting in South Sudan in July 2016 was followed by people seeking safety in Uganda. Ugandan authorities and UNHCR documented people fleeing conflict and limited food availability. Refugee arrivals are a distinct protection measure.',source='https://www.unhcr.ca/news/uganda-unhcr-statement-south-sudan/'),
 dict(id=26,scope='route',origin='ETH',destination='SDN',route='Ethiopia → Sudan',start=2020,end=2020,title='Flight from fighting in Tigray',text='Fighting that began in Ethiopia’s Tigray region in November 2020 forced people to seek safety across the border in eastern Sudan. UNHCR documented refugee arrivals and emergency assistance. These reports describe this displacement episode, not all migration between Ethiopia and Sudan.',source='https://www.unhcr.ca/news/ethiopia-refugee-numbers-sudan-cross-40000-mark/'),
 dict(id=27,scope='origin-country',country='NIC',start=2018,end=2018,title='Repression after the April protests',text='Following protests in April 2018, the Inter-American Commission on Human Rights documented persecution and serious human rights violations in Nicaragua, alongside increased departures and asylum seeking, especially in Costa Rica and elsewhere in the Americas. This country context does not identify the reason for each individual movement.',source='https://www.oas.org/en/iachr/media_center/PReleases/2018/183.asp'),
 dict(id=28,scope='origin-country',country='HTI',start=2024,end=2024,title='Gang violence and insecurity',text='In 2024, escalating gang violence, threats and instability deepened Haiti’s humanitarian crisis. UNHCR described large-scale internal displacement as well as protection needs for Haitians abroad. Internal displacement figures must not be counted as international migration, and this context cannot assign a total to any destination.',source='https://dataviz.unhcr.org/product-gallery/2024/10/haiti-a-multi-dimensional-crisis-leading-to-continued-displacement/'),
 dict(id=29,scope='origin-country',country='RWA',start=1994,end=1994,title='Genocide, war and regional displacement',text='The genocide against the Tutsi, war and political upheaval in Rwanda in 1994 caused immense loss of life and displacement. People fled to neighbouring countries, including Tanzania and Zaire, now the Democratic Republic of the Congo. The OAU and UNHCR documented these movements and subsequent protection and return challenges. Modern map boundaries and annual migration estimates do not capture every aspect of this crisis.',source='https://www.refworld.org/reference/confdoc/oau/1995/38573'),
 dict(id=30,scope='route',origin='CUB',destination='USA',route='Cuba → United States',start=1980,end=1980,title='The Mariel boatlift',text='The opening of the port of Mariel in 1980 enabled a major wave of departures from Cuba to Florida. The US National Archives documents the political decisions, boat journeys and US reception response. This specific episode should not be treated as the beginning of all Cuban migration or equated with the entire corridor total.',source='https://text-message.blogs.archives.gov/2021/08/03/the-causes-and-effects-of-the-mariel-boatlift/'),
 dict(id=31,scope='route',origin='VNM',destination='USA',route='Vietnam → United States',start=1975,end=1975,title='Evacuation at the end of the war',text='The final days before the fall of Saigon in April 1975 included the evacuation of Vietnamese people associated with the former South Vietnamese government, followed by resettlement in the United States. UNHCR’s historical account distinguishes this evacuation from later refugee departures and other migration.',source='https://www.unhcr.org/africa/sites/afr/files/legacy-pdf/3ebf9bad0.pdf')
])
for event in events:
    event['catalogReviewedAt'] = '2026-11-06'
    event['evidenceType'] = 'sourced_historical_context_not_causal_attribution'
p=pathlib.Path(__file__).parent/'dist/data/events.json';json.dump(events,open(p,'w'))
